package cn.bidcheck.verification.engine;

import cn.bidcheck.consistency.ConsistencyDerivedConclusion;
import cn.bidcheck.domain.Domain.Document;
import cn.bidcheck.domain.Domain.Evidence;
import cn.bidcheck.domain.Domain.Page;
import java.util.*;
import org.junit.jupiter.api.Test;
import static cn.bidcheck.verification.engine.VerificationTypes.*;
import static org.junit.jupiter.api.Assertions.*;

class ConfirmedConsistencyRelationTest {
    Document document(){return new Document("bid","project","BID","bid.pdf",1,"source-hash","",cn.bidcheck.compat.Java8Api.listOf(new Page(1,"项目名称：北方办公楼装修工程\n投标文件（商务部分）","PAGE","TEXT",""), new Page(2,"本项目人员配置\n项目负责人：李明","PAGE","TEXT",""), new Page(3,"本项目人员配置\n项目负责人：李明","PAGE","TEXT",""), new Page(4,"本项目人员配置\n项目负责人：李明","PAGE","TEXT","")),cn.bidcheck.compat.Java8Api.listOf());}
    Map<String,Object> occurrence(Document d,int page,String id){Page p=d.pages().stream().filter(x->x.number()==page).findFirst().orElseThrow(java.util.NoSuchElementException::new);return linked("id",id,"field","personName","value","李明","subject","项目负责人","scope","CURRENT_PROJECT","sourceOffset",0,"evidence",new Evidence(d.id(),d.name(),page,"PAGE",p.text(),"chars:0-"+p.text().length(),1));}
    List<Map<String,Object>> confirmed(Document d){cn.bidcheck.verification.engine.EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(d));java.util.List<cn.bidcheck.verification.engine.VerificationTypes.Source> selected=cn.bidcheck.compat.Java8Api.toList(c.all.stream().filter(s->cn.bidcheck.compat.Java8Api.setOf(2, 3).contains(s.evidence().page())));java.util.List<java.util.Map<java.lang.String, java.lang.Object>> citations=cn.bidcheck.compat.Java8Api.toList(selected.stream().map(s->linked("sourceId",s.id(),"documentId",d.id(),"documentHash",d.sha256(),"documentVersion",d.version(),"page",s.evidence().page(),"locationType",s.evidence().locationType(),"quote",s.evidence().quote())));java.util.Map<java.lang.String, java.lang.Object> proposed=linked("kind","RELATION","subject","李明","field","同一人","rawValue","李明","value","李明","scope","CURRENT_PROJECT","sourceIds",cn.bidcheck.compat.Java8Api.toList(selected.stream().map(Source::id)),"attributes",cn.bidcheck.compat.Java8Api.mapOf("object", "李明"));java.util.Map<java.lang.String, java.lang.Object> record=linked("id","claim","status","CONFIRMED","actor","reviewer","decidedAt","2026-11-02","confirmationLedgerId","ledger-claim","revision","v1","targetId","identity","targetFingerprint","target-hash","proposedFact",proposed,"evidences",citations);return ConfirmedInferenceEvidence.validated(cn.bidcheck.compat.Java8Api.listOf(record),cn.bidcheck.compat.Java8Api.listOf(d));}
    Map<String,Object> report(Document d,List<Map<String,Object>> occurrences,List<Map<String,Object>> relations){return linked("documentId",d.id(),"documentHash",d.sha256(),"occurrences",occurrences,"confirmedEvidenceRelations",relations,"groups",cn.bidcheck.compat.Java8Api.listOf(linked("id","group","field","personName","status","EVIDENCE_INSUFFICIENT","occurrenceIds",cn.bidcheck.compat.Java8Api.toList(occurrences.stream().map(o->o.get("id"))))));}
    @Test void confirmedExactPairIsUsedWithoutApprovingAnotherSameNamePage(){
        cn.bidcheck.domain.Domain.Document d=document();java.util.List<java.util.Map<java.lang.String, java.lang.Object>> relation=confirmed(d);assertEquals(1,relation.size());assertTrue(ConfirmedInferenceEvidence.isValidated(relation.get(0)));java.util.Map<java.lang.String, java.lang.Object> pair=report(d,cn.bidcheck.compat.Java8Api.listOf(occurrence(d,2,"a"), occurrence(d,3,"b")),relation);assertEquals("PASS",ConsistencyDerivedConclusion.recompute(d,pair).get("group").status());assertEquals("EVIDENCE_INSUFFICIENT",RuleEvaluator.maps(pair.get("groups")).get(0).get("status"));
        java.util.Map<java.lang.String, java.lang.Object> additional=report(d,cn.bidcheck.compat.Java8Api.listOf(occurrence(d,2,"a"), occurrence(d,3,"b"), occurrence(d,4,"c")),relation);assertEquals("UNDETERMINED",ConsistencyDerivedConclusion.recompute(d,additional).get("group").status());
    }
    @Test void tamperedReceiptAndHistoryCannotUseAnOtherwiseConfirmedEdge(){
        cn.bidcheck.domain.Domain.Document d=document();java.util.LinkedHashMap<java.lang.String, java.lang.Object> relation=new LinkedHashMap<>(confirmed(d).get(0));relation.put("subject","王强");assertFalse(ConfirmedInferenceEvidence.isValidated(relation));assertEquals("UNDETERMINED",ConsistencyDerivedConclusion.recompute(d,report(d,cn.bidcheck.compat.Java8Api.listOf(occurrence(d,2,"a")),cn.bidcheck.compat.Java8Api.listOf(relation))).get("group").status());
        java.util.Map<java.lang.String, java.lang.Object> old=occurrence(d,2,"history");old.put("scope","HISTORICAL_PROJECT");assertEquals("UNDETERMINED",ConsistencyDerivedConclusion.recompute(d,report(d,cn.bidcheck.compat.Java8Api.listOf(old),confirmed(d))).get("group").status());
    }
    @Test void originalWarningIsNotOverwrittenByConfirmedIdentity(){cn.bidcheck.domain.Domain.Document d=document();java.util.Map<java.lang.String, java.lang.Object> report=report(d,cn.bidcheck.compat.Java8Api.listOf(occurrence(d,2,"a"), occurrence(d,3,"b")),confirmed(d));java.util.Map<java.lang.String, java.lang.Object> group=cn.bidcheck.consistency.ConsistencyRunSupport.maps(report.get("groups")).get(0);group.put("status","WARNING");assertTrue(ConsistencyDerivedConclusion.recompute(d,report).isEmpty());assertEquals("WARNING",group.get("status"));}
}
